from fractions import Fraction as F
rows=[('A',15,[1,0,0,1]),('A',9,[0,1,1,1]),('B',6,[1,0,0,0]),('B',5,[0,1,0,0]),('C',9,[1,1,1,1]),('C',5,[0,1,1,0]),('D',14,[0,0,0,0]),('D',9,[1,1,1,0])]
tests='TUVW'; modes='ABCD'
loss=[[0,24,11,6],[19,0,19,8],[9,10,0,16],[21,24,20,0]]
cost=list(map(F,['0.8','1.2','0.7','1.4']))
def stop(ids):
 w=sum(rows[i][1] for i in ids)
 return min((sum(F(rows[i][1]*loss[a][modes.index(rows[i][0])],w) for i in ids),modes[a]) for a in range(4))
def val(ids,available,budget):
 best=stop(ids)
 if budget:
  w=sum(rows[i][1] for i in ids)
  for t in available:
   v=cost[t]
   for x in (0,1):
    sub=[i for i in ids if rows[i][2][t]==x]
    if sub:v+=F(sum(rows[i][1] for i in sub),w)*val(sub,[u for u in available if u!=t],budget-1)[0]
   best=min(best,(v,tests[t]))
 return best
ids=list(range(8)); total=sum(r[1] for r in rows)
first_losses={'STOP':float(stop(ids)[0])}
nexts={}
for t in range(4):
 v=cost[t]; branches={}
 for x in (0,1):
  sub=[i for i in ids if rows[i][2][t]==x]
  if sub:
   b=val(sub,[u for u in range(4) if u!=t],1)
   v+=F(sum(rows[i][1] for i in sub),total)*b[0]
   branches[str(x)]=b[1]
  else:branches[str(x)]='IMPOSSIBLE'
 first_losses[tests[t]]=float(v);nexts[tests[t]]=branches
best=val(ids,list(range(4)),2)
print({'first':best[1],'first_losses':first_losses,'next':nexts.get(best[1],{})})

