from fractions import Fraction as F
# V=0 filters the persistent latent row; repeated display is not new evidence.
rows=[('A',15,1,0,1),('B',6,1,0,0),('B',5,0,1,0),('D',14,0,0,0)] # mode, weight, T,U,W
modes='ABCD'; loss=[[0,24,11,6],[19,0,19,8],[9,10,0,16],[21,24,20,0]]
def repairs(rs):
 s=sum(r[1] for r in rs)
 return {a:sum(F(r[1]*loss[i][modes.index(r[0])],s) for r in rs) for i,a in enumerate(modes)}
s=sum(r[1] for r in rows)
posterior={a:float(F(sum(r[1] for r in rows if r[0]==a),s)) for a in modes}
v=repairs(rows); out={a:float(x) for a,x in v.items()}; policies={}
for j,(t,c) in enumerate([('T',F('0.8')),('U',F('1.2')),('W',F('7.4'))],2):
 value=c; policy={}
 for x in (0,1):
  rs=[r for r in rows if r[j]==x]
  if not rs: policy[str(x)]='IMPOSSIBLE';continue
  rr=repairs(rs); a=min(rr,key=rr.get)
  policy[str(x)]=a
  value+=F(sum(r[1] for r in rs),s)*rr[a]
 out[t]=float(value);policies[t]=policy
a=min(out,key=out.get)
print({'posterior':posterior,'remaining_losses':out,'action':a,'repair_after':policies.get(a,{})})

